using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Diagnostics;
using System.Windows.Forms;
using System.Web.Script.Serialization;
namespace Aster {
public class SupportCase {
 public int Version=1; public string Title,Category,Symptom,Report,Question,Answer,Notes; public DateTime Saved;
 public override string ToString(){return Saved.ToString("g")+" · "+Title;}
}
static class CaseStore {
 public static string Folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Pulse","Cases");
 public static SupportCase Read(string path){if(new FileInfo(path).Length>1048576)throw new Exception("Case exceeds 1 MB.");var value=new JavaScriptSerializer{MaxJsonLength=1048576}.Deserialize<SupportCase>(File.ReadAllText(path));if(value==null||value.Version!=1||string.IsNullOrWhiteSpace(value.Title))throw new Exception("Unsupported or incomplete case file.");return value;}
 public static string Save(string folder,SupportCase value){Directory.CreateDirectory(folder);value.Saved=DateTime.Now;string p=Path.Combine(folder,DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N")+".json");string data=new JavaScriptSerializer{MaxJsonLength=1048576}.Serialize(value);if(Encoding.UTF8.GetByteCount(data)>1048576)throw new Exception("Case exceeds 1 MB. Shorten its notes or report.");File.WriteAllText(p+".tmp",data,Encoding.UTF8);File.Move(p+".tmp",p);return p;}
}
class ErrorHelp {
 public string Code,Meaning,Next,Url;
 public override string ToString(){return Code+" · "+Meaning;}
 const string Root="https://learn.microsoft.com/en-us/troubleshoot/";
 public static ErrorHelp[] All={
 new ErrorHelp{Code="0x80070005",Meaning="Access denied",Next="Identify which app or update failed and the affected resource. Do not broadly change permissions or disable security.",Url=Root+"windows-client/installing-updates-features-roles/troubleshoot-windows-update-error-0x80070005"},
 new ErrorHelp{Code="0x80070002",Meaning="File not found",Next="Record the failing operation and missing-file path from its log. The code alone does not identify which file or why it is missing.",Url=Root+"windows-server/installing-updates-features-roles/troubleshoot-windows-update-error-0x80070002"},
 new ErrorHelp{Code="0x80070070",Meaning="Insufficient disk space",Next="Review free space on the affected volume and Windows Storage settings. Review files before deleting them.",Url=Root+"windows-server/installing-updates-features-roles/troubleshoot-windows-update-error-0x80070070"},
 new ErrorHelp{Code="0x800f081f",Meaning="Servicing source missing",Next="Identify the feature or servicing operation and Windows version. A compatible repair source may be needed; do not use an arbitrary ISO.",Url=Root+"windows-client/application-management/dotnet-framework-35-installation-error"},
 new ErrorHelp{Code="0x800f0906",Meaning="Servicing source download failed",Next="Check the operation, connectivity and managed update policies. On a managed PC, ask IT before changing its update source.",Url=Root+"windows-client/application-management/dotnet-framework-35-installation-error"}};
 public static string Summarize(string text){var codes=Regex.Matches(text,@"\b0x[0-9a-fA-F]{8}\b",RegexOptions.IgnoreCase).Cast<Match>().Select(x=>x.Value.ToLowerInvariant()).Distinct().ToArray();var exits=Regex.Matches(text,@"Exit code:\s*(-?\d+)",RegexOptions.IgnoreCase).Cast<Match>().Select(x=>x.Groups[1].Value).ToArray();return "LOCAL LOG INDEX · pattern matching, not AI diagnosis\r\n"+"Recorded exit codes: "+(exits.Length==0?"none found":string.Join(", ",exits))+"\r\nZero alone does not prove the original symptom is fixed. Missing codes do not prove success.\r\n\r\n"+(codes.Length==0?"No hexadecimal error codes found.":string.Join("\r\n",codes.Select(c=>{var h=All.FirstOrDefault(x=>x.Code==c);return c+" · "+(h==null?"not in the offline library":h.Meaning); })))+"\r\n\r\nORIGINAL LOG\r\n"+text;}
}
