 }
 void Guard(Action action){try{action();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Aster");}}
 void RefreshCases(){Guard(()=>{caseList.Items.Clear();casePaths=Directory.Exists(CaseStore.Folder)?Directory.GetFiles(CaseStore.Folder,"*.json").OrderByDescending(File.GetLastWriteTime).Take(300).ToArray():new string[0];foreach(string p in casePaths){try{caseList.Items.Add(CaseStore.Read(p));}catch{caseList.Items.Add("Unreadable case · "+Path.GetFileName(p));}}});}
}
